class Solution {
  private static final int MOD = 1337;

  public int superPow(int a, int[] b) {
    // a^(10x + d) = (a^x)^10 * a^d
    int result = 1;
    for (int d : b) result = pow(result, 10) * pow(a, d) % MOD;
    return result;
  }

  private int pow(int base, int exp) {
    base %= MOD;
    int r = 1;
    for (int i = 0; i < exp; i++) r = r * base % MOD;
    return r;
  }
}
